class ConfigBuilder<T extends Partial<Config> = {}> {
  private cfg: Partial<Config> = {};
  withHost(host: string): ConfigBuilder<T & { host: string }> {
    this.cfg.host = host; return this as any;
  }
  build(this: ConfigBuilder<Config>): Config { return this.cfg as Config; }
}
